import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quoting a premium — price list", () => {
    it("quotes a sword: base 100 G + 10 % first-insurance surcharge + 5 G fee = 115 G", () => {
      const scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
          },
        ],
      };

      expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
    });
    it("quotes an amulet: base 60 G + 10 % + 5 G = 71 G", () => {
      const scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
          },
        ],
      };

      expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
    });
    it("quotes a staff: base 80 G + 10 % + 5 G = 93 G", () => {
      const scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }],
          },
        ],
      };

      expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
    });
    it.todo("quotes a potion: base 40 G + 10 % + 5 G = 49 G");
    it.todo("quotes a single rune component: base 25 G + 10 % + 5 G = 33 G");
    it.todo("quotes a single moonstone component: base 25 G + 10 % + 5 G = 33 G");
    it.todo("sums the base premiums of several main items: sword + potion = 140 G base, + 10 % + 5 G = 159 G");
  });

  describe("quoting a premium — component building blocks", () => {
    it.todo("charges 60 G for a building block of 3 alike components instead of 75 G: + 10 % + 5 G = 71 G");
    it.todo("charges 60 G + 25 G for 4 alike components: + 10 % + 5 G = 99 G");
    it.todo("charges 120 G for 6 alike components (two building blocks): + 10 % + 5 G = 137 G");
    it.todo("does not form a building block from unalike components: 2 runes + 1 moonstone = 75 G base, + 10 % + 5 G = 88 G");
  });

  describe("quoting a premium — risk surcharges", () => {
    it.todo("adds a 50 % risk surcharge for a cursed sword: 150 G, + 10 % + 5 G = 170 G");
    it.todo("adds a 30 % risk surcharge for a highly enchanted sword (enchantment 5): 130 G, + 10 % + 5 G = 148 G");
    it.todo("does not add the enchantment surcharge below level 5 (enchantment 4): 100 G, + 10 % + 5 G = 115 G");
    it.todo("applies both surcharges to a cursed, highly enchanted sword: 100 × 1.5 × 1.3 = 195 G, + 10 % + 5 G = 220 G");
    it.todo("applies risk surcharges per item, not to the whole policy: cursed sword + plain potion = 190 G, + 10 % + 5 G = 214 G");
  });

  describe("quoting a premium — customer modifiers", () => {
    it.todo("gives a 20 % loyalty discount to a customer of 2 years: sword 100 × 1.1 × 0.8 = 88 G + 5 G = 93 G");
    it.todo("gives no loyalty discount to a customer of 1 year: sword = 115 G");
    it.todo("applies the 10 % initial assessment surcharge only to the first contract");
    it.todo("gives a 15 % discount on the second contract: sword 100 × 0.85 + 5 G = 90 G");
    it.todo("gives the 15 % discount on the third contract as well: sword 100 × 0.85 + 5 G = 90 G");
    it.todo("combines loyalty and repeat-contract discounts on a later contract: sword 100 × 0.8 × 0.85 + 5 G = 73 G");
    it.todo("adds the 5 G processing fee to every premium, including repeat contracts");
  });

  describe("quoting a premium — rounding", () => {
    it.todo("rounds the premium up, in the MHPCO's favor: amulet for a 5-year customer 60 × 1.1 × 0.8 = 52.8 → 53 G + 5 G = 58 G");
  });

  describe("processing claims — deductible and reimbursement", () => {
    it.todo("subtracts the 100 G deductible from the damage amount: 200 G damage on an amulet pays out 100 G");
    it.todo("pays out 0 G when the damage does not exceed the deductible: 100 G damage pays out 0 G");
    it.todo("applies the deductible once per damage event, not per damaged item: two 200 G damages in one incident pay out 300 G");
    it.todo("reimburses damage to an item with enchantment 8 at 50 %: 500 G damage → 250 G − 100 G deductible = 150 G");
    it.todo("reimburses damage to an item with enchantment 7 in full: 500 G damage → 400 G");
    it.todo("fully reimburses damage to an item made of dragon material even at enchantment 8: 500 G damage → 400 G");
  });

  describe("processing claims — payout cap", () => {
    it.todo("reports the remaining cap after a claim: amulet insured at 600 G has a 1200 G cap, 200 G damage leaves 1100 G");
    it.todo("caps the payout at twice the insurance sum: a single huge claim on an amulet pays at most 1200 G and leaves 0 G");
    it.todo("caps the cumulative payout across several claims on the same policy");
    it.todo("pays out 0 G once the cap is exhausted");
    it.todo("bases the cap on the summed insurance value of all insured items: sword + amulet = 1600 G insured → 3200 G cap");
    it.todo("tracks caps of several policies independently");
  });

  describe("scenario processing", () => {
    it.todo("returns an empty results array for a scenario without steps");
    it.todo("returns one result per step, in order, matching the schema example 1 shape");
    it.todo("processes a quote followed by two claims against it, as in schema example 2");
  });
});

