export type Item = { type: string };
export type Step = { items: Item[] };
export type Scenario = { steps: Step[] };
export type Result = { premium: number };
export type ScenarioOutcome = { results: Result[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE = 1.1;
const PROCESSING_FEE = 5;

// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
// exact value over a whole-gold boundary and inflating the premium by 1 G.
const FLOAT_ARTIFACT_PRECISION = 6;

const roundUpToWholeGold = (amount: number): number =>
  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const totalBasePremium = scenario.steps[0].items.reduce(
    (total, item) => total + basePremiumOf(item),
    0,
  );
  const premium =
    roundUpToWholeGold(totalBasePremium * FIRST_INSURANCE_SURCHARGE) +
    PROCESSING_FEE;
  return { results: [{ premium }] };
};

