const HIGH_ENCHANTMENT_SURCHARGE = 1.3;
const HIGH_ENCHANTMENT_LEVEL = 5;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

const riskFactorOf = (item: Item): number => {
  if (item.cursed) return CURSED_SURCHARGE;
  if (isHighlyEnchanted(item)) return HIGH_ENCHANTMENT_SURCHARGE;
